### Core Data Model (`types.ts`)

```typescript
// Global state shape
interface AppState {
  therapist: {
    name: string
    slug: string
    title: string
    photoUrl: string
    bio: string
    specializations: string[]
    languages: string[]
    sessionDuration: number       // in minutes
    bufferMinutes: number
    tier: 'STARTER' | 'PRO' | 'CLINIC'
  }
  billing: {
    clinicName: string
    email: string
    gstin: string
    paymentMethod: string
    address: string
  }
  tierConfigs: Record<'STARTER' | 'PRO' | 'CLINIC', TierConfig>
  services: Service[]                // consultation services shown on booking page
  packages: Package[]                // 3/6/12 session bundles
  clients: Client[]                  // CRM client directory
  sessions: Session[]                // confirmed/completed/cancelled appointments
  notes: Note[]                      // SOAP/DAP/Freeform clinical notes
  messages: Message[]                // care chat messages (therapist↔client)
  blockedDates: {date: string; reason: string}[]
  selectedServiceIdx: number
  selectedSlot: string
  activeTemplate: 'SOAP' | 'DAP' | 'FREEFORM'
  clientPackageCredits: number
}

// Tier config — gated by canAccess()
interface TierConfig {
  tierKey: 'STARTER' | 'PRO' | 'CLINIC'
  name: string
  priceINR: number
  maxClients: number
  templates: ('FREEFORM' | 'SOAP' | 'DAP' | 'BIRP')[]
  packagesAllowed: boolean
  advancedAnalytics: boolean
}
```

Every UI branch calls `canAccess(featureKey, context)` **before rendering**. No feature is available without an explicit entitlement check. This is the single source of truth that prevents "feature rot" and keeps the code from being AI-sloppy (generic everything-enabled).

---

### Entitlement Engine (`entitlement.ts`)

```typescript
function canAccess(featureKey: string, context: { [key: string]: any } = {}): {
  allowed: boolean
  reason: string
  current?: number
  limit?: number
} {
  const cfg = appState.tierConfigs[appState.therapist.tier] || appState.tierConfigs.PRO

  // Example gates:
  if (featureKey === 'ADD_ACTIVE_CLIENT') {
    const allowed = appState.clients.length < cfg.maxClients
    return {
      allowed,
      current: appState.clients.length,
      limit: cfg.maxClients,
      reason: `Your ${cfg.name} (${appState.therapist.tier}) plan caps active clients at ${cfg.maxClients} (currently ${appState.clients.length}). Upgrade your plan or increase the cap in 'Subscription & Plan Admin'!`
    }
  }
  if (featureKey === 'NOTE_TEMPLATE') {
    const allowed = cfg.templates.includes(context.template)
    return {
      allowed,
      reason: `The '${context.template}' clinical template is not enabled on ${cfg.name}. Allowed: ${cfg.templates.join(', ')}. You can customize this in 'Subscription & Plan Admin'.`
    }
  }
  if (featureKey === 'SESSION_PACKAGES') {
    return { allowed: cfg.packagesAllowed, reason: `Creating custom multi-session bundles is disabled on ${cfg.name}. Enable it in 'Subscription & Plan Admin' or switch to PRO.` }
  }
  if (featureKey === 'ADVANCED_ANALYTICS') {
    return { allowed: cfg.advancedAnalytics, reason: `Service cohort analytics are disabled on ${cfg.name}. Switch to PRO or enable them in 'Subscription & Plan Admin'.` }
  }
  // Default: allowed for features not explicitly gated
  return { allowed: true }
}
```

**Why this matters**: Every `if (!canAccess(...))` guard is a design decision, not an afterthought. The frontend-design skill warns against "template chrome that appears whatever the subject" — the entitlement engine ensures every UI element is a deliberate choice tied to a tier boundary.

