{"kind":"tool","id":"jUy9VADFmS8","toolName":"write_file","input":{"path":"src/views/Landing.tsx","instructions":"Rebuild landing hero to match the mint/pill reference","content":"import { Badge, Icon, cx } from "../components/ui";
import { activeClients } from "../lib/entitlements";
import {
  dateLabel,
  inr,
  isoPlus,
  slotsFor,
  timeLabel,
  todayISO,
  upcoming,
} from "../lib/format";
import { useStore } from "../lib/store";

const FLOWS = [
  {
    icon: "calendar",
    title: "Booking that cannot double-book",
    body: "Slots come from your duration, buffer and working days — then lock the moment a client pays. Closed dates override the calendar without deleting it.",
    href: "#/public",
    cta: "Open the branded page",
  },
  {
    icon: "note",
    title: "Notes the client never sees",
    body: "SOAP and DAP structure with a visibility switch per note. Private notes are filtered before anything is serialised to the portal, not hidden in the UI.",
    href: "#/console",
    cta: "Open the console",
  },
  {
    icon: "users",
    title: "Packages, not one-off invoices",
    body: "Three, six and twelve session bundles sell up front and draw down session by session, so a course of therapy has a ledger instead of a chat thread.",
    href: "#/console",
    cta: "See the billing ledger",
  },
];

export function Landing() {
  const { state } = useStore();
  const t = state.therapist;
  const tier = state.tiers[t.tier];
  const today = todayISO();
  const todays = state.appointments.filter((a) => a.date === today && a.status !== "CANCELLED");
  const net = state.invoices.reduce((sum, i) => sum + i.net, 0);
  const next = upcoming(state)[0];

  const nextOpen = (() => {
    for (let i = 0; i < 7; i += 1) {
      const d = isoPlus(i);
      const open = slotsFor(state, d, t.sessionDuration);
      if (open[0]) return `${i === 0 ? "Today" : dateLabel(d)} · ${timeLabel(open[0])}`;
    }
    return "Fully booked";
  })();

  return (
    <div className="mx-auto max-w-[1180px] px-4 sm:px-6">
      {/* Hero */}
      <section className="grid items-center gap-10 pb-12 pt-8 lg:grid-cols-[1.02fr_1fr] lg:gap-12 lg:pb-16 lg:pt-12">
        <div>
          <span className="inline-flex items-center gap-2 rounded-full bg-mint px-3.5 py-2 text-[12px] font-semibold text-pine">
            <span className="h-1.5 w-1.5 rounded-full bg-pine" />
            Trusted by independent practitioners across India
          </span>

          <h1 className="display mt-6 text-[clamp(2.6rem,5.6vw,4.1rem)] text-ink">
            Your practice,
            <br />
            <span className="text-pine">one calm place.</span>
          </h1>

          <p className="mt-5 max-w-[46ch] text-[14.5px] font-medium leading-relaxed text-ink-2">
            Scheduling, SOAP and DAP notes, prepaid packages, Razorpay billing and the client
            relationship — held in one console behind one branded link, with a clear line around what
            a client is allowed to read.
          </p>

          <div className="mt-8 flex flex-wrap items-center gap-3">
            <a
              href="#/console"
              className="inline-flex h-12 items-center gap-2 rounded-full bg-pine px-6 text-[13.5px] font-bold text-white shadow-glow transition-colors hover:bg-[#188a55]"
            >
              Open practice console
              <Icon name="arrow" className="h-4 w-4" strokeWidth={2} />
            </a>
            <a
              href="#/public"
              className="inline-flex h-12 items-center gap-2 rounded-full border border-rule-strong bg-paper px-6 text-[13.5px] font-semibold text-ink transition-colors hover:bg-paper-2"
            >
              Explore services
            </a>
          </div>

          <ul className="mt-8 flex flex-wrap gap-2.5">
            {[
              { icon: "clock", label: "Instant slot lock" },
              { icon: "shield", label: "Notes stay private" },
              { icon: "check", label: "No lock-in contract" },
            ].map((c) => (
              <li
                key={c.label}
                className="inline-flex items-center gap-2 rounded-full border border-rule bg-paper px-3 py-2 text-[11.5px] font-semibold text-ink-2 shadow-soft"
              >
                <Icon name={c.icon} className="h-3.5 w-3.5 text-pine" strokeWidth={2} />
                {c.label}
              </li>
            ))}
          </ul>
        </div>

        {/* Hero visual */}
        <div className="relative">
          <div className="absolute -inset-4 -z-10 rounded-[42px] bg-mint/70" />
          <div className="relative overflow-hidden rounded-[32px] bg-mint">
            <img
